<template><div class="space-y-3 p-4"><h1 class="text-xl font-bold text-slate-800">Requests with offers</h1><NuxtLink v-for="item in requests" :key="item.id" :to="`/buyer/compare?request_id=${item.id}`" class="m-card block"><p class="text-sm font-semibold text-slate-800">{{ item.title }}</p><p class="mt-2 text-xs text-indigo-600">Open comparison</p></NuxtLink></div></template>
<script setup lang="ts">definePageMeta({ middleware: ['auth'] }); const { listProcurementRequests } = useCommerce(); const requests = ref<any[]>([]); onMounted(async () => { requests.value = (await listProcurementRequests()).items.filter((item: any) => ['offer_received', 'awarded'].includes(item.status)) })</script>
